#!/usr/bin/env bash
# Copies the files generated by `python3 -m docker_notify setup` into the user's systemd dirs.
set -euo pipefail

NAME=docker-notify
SRC="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/system"
CONF_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
CONF_DIR="$CONF_HOME/$NAME"
UNIT_DIR="$CONF_HOME/systemd/user"

die() { echo "error: $*" >&2; exit 1; }

[ "$(id -u)" -ne 0 ] || die "run as your normal user, not root"
for f in env "$NAME.service" "$NAME.timer"; do
  [ -f "$SRC/$f" ] || die "$SRC/$f not found. Run 'python3 -m docker_notify setup' first."
done
systemctl --user show-environment >/dev/null 2>&1 || die "no systemd user session"

install -d -m 700 "$CONF_DIR"
install -m 600 "$SRC/env" "$CONF_DIR/env"
install -d -m 755 "$UNIT_DIR"
install -m 644 "$SRC/$NAME.service" "$SRC/$NAME.timer" "$UNIT_DIR/"

systemctl --user daemon-reload
systemctl --user enable --now "$NAME.timer"

me="$(id -un)"
if [ "$(loginctl show-user "$me" -p Linger --value 2>/dev/null)" != yes ]; then
  echo "Without lingering, the timer only runs while you're logged in."
  read -r -p "Enable lingering for $me? [y/N] " a || a=n
  if [[ ${a:-n} =~ ^[Yy] ]]; then
    loginctl enable-linger "$me" || sudo loginctl enable-linger "$me"
  fi
fi

systemctl --user list-timers "$NAME.timer" --no-pager
echo "Test it now with: systemctl --user start $NAME.service"